<?php
require_once 'config.php';require_login();$pdo=db();$projects=allowed_projects('view_project');
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$pid=(int)($_POST['project_id']??0);$hid=(int)($_POST['head_id']??0);$employee=(int)($_POST['advance_employee_id']??0);$date=(string)($_POST['entry_date']??'');$amount=$_POST['amount']??0;$action=$_POST['action']??'add';
 if(!can($action==='edit'?'edit_expense':'add_expense',$pid)||!valid_date($date)||!positive_money($amount)){http_response_code(403);exit('Invalid permission, date or amount');}
 $s=$pdo->prepare("SELECT h.id FROM expense_heads h JOIN projects p ON p.id=h.project_id WHERE h.id=? AND h.project_id=? AND p.status!='closed'");$s->execute([$hid,$pid]);if(!$s->fetchColumn())exit('Invalid expense head or closed project');
 if($employee){$s=$pdo->prepare('SELECT id FROM users WHERE id=? AND active=1');$s->execute([$employee]);if(!$s->fetchColumn())exit('Invalid employee');}
 if($employee){$assignment=$pdo->prepare('SELECT 1 FROM project_assignments WHERE project_id=? AND user_id=?');$assignment->execute([$pid,$employee]);if(!$assignment->fetchColumn()){http_response_code(403);exit('Employee is not assigned to this project.');}}
if($action==='edit'){
  $id=(int)($_POST['id']??0);$s=$pdo->prepare('SELECT project_id FROM expenses WHERE id=?');$s->execute([$id]);$old=$s->fetch();if(!$old||!can('edit_expense',(int)$old['project_id'])){http_response_code(403);exit('Edit denied');}
  $s=$pdo->prepare("UPDATE expenses SET project_id=?,head_id=?,entry_date=?,amount=?,description=?,advance_employee_id=?,status='pending',approved_by=NULL WHERE id=?");$s->execute([$pid,$hid,$date,$amount,trim($_POST['description']??''),$employee?:null,$id]);
 }else{$s=$pdo->prepare('INSERT INTO expenses(project_id,head_id,entry_date,amount,description,entered_by,advance_employee_id) VALUES(?,?,?,?,?,?,?)');$s->execute([$pid,$hid,$date,$amount,trim($_POST['description']??''),user()['id'],$employee?:null]);}
 flash('Expense saved and awaiting approval.');redirect('expenses.php');
}
if(is_admin())$rows=$pdo->query('SELECT e.*,p.title project_title,h.name head_name,u.name user_name FROM expenses e JOIN projects p ON p.id=e.project_id JOIN expense_heads h ON h.id=e.head_id JOIN users u ON u.id=e.entered_by ORDER BY e.entry_date DESC,e.id DESC LIMIT 500')->fetchAll();
else{$s=$pdo->prepare('SELECT e.*,p.title project_title,h.name head_name,u.name user_name FROM expenses e JOIN projects p ON p.id=e.project_id JOIN expense_heads h ON h.id=e.head_id JOIN users u ON u.id=e.entered_by JOIN project_assignments a ON a.project_id=p.id WHERE a.user_id=? AND a.view_project=1 ORDER BY e.entry_date DESC,e.id DESC LIMIT 500');$s->execute([user()['id']]);$rows=$s->fetchAll();}
$heads=$pdo->query('SELECT id,project_id,name FROM expense_heads ORDER BY name')->fetchAll();$employees=$pdo->query('SELECT id,name FROM users WHERE active=1 ORDER BY name')->fetchAll();
include 'layout_top.php';?>
<section class="page-title"><div><h1>দৈনিক ব্যয় এন্ট্রি</h1><p>প্রকল্প অনুযায়ী খাত নির্বাচন করুন; কর্মীর অগ্রিম থেকে খরচ হলে কর্মী নির্বাচন করুন।</p></div></section>
<section class="panel"><h2>ব্যয় যোগ / সংশোধন</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" id="action" name="action" value="add"><input type="hidden" id="rid" name="id"><div><label>প্রকল্প</label><select id="pid" name="project_id" required onchange="filterHeads()"><option value="">নির্বাচন করুন</option><?php foreach($projects as $p):if($p['status']==='closed'||!can('add_expense',(int)$p['id']))continue;?><option value="<?=$p['id']?>"><?=e($p['title'])?></option><?php endforeach;?></select></div><div><label>ব্যয়ের খাত</label><select id="hid" name="head_id" required><option value="">প্রথমে প্রকল্প নির্বাচন করুন</option><?php foreach($heads as $h):?><option data-project="<?=$h['project_id']?>" value="<?=$h['id']?>"><?=e($h['name'])?></option><?php endforeach;?></select></div><div><label>অগ্রিম গ্রহণকারী কর্মী (ঐচ্ছিক)</label><select id="emp" name="advance_employee_id"><option value="0">সাধারণ প্রকল্প ব্যয়</option><?php foreach($employees as $u):?><option value="<?=$u['id']?>"><?=e($u['name'])?></option><?php endforeach;?></select></div><div><label>ব্যয়ের তারিখ</label><input id="dt" type="date" name="entry_date" value="<?=date('Y-m-d')?>" required></div><div><label>টাকার পরিমাণ</label><input id="amt" type="number" min=".01" step=".01" name="amount" required></div><div class="wide"><label>বিবরণ</label><input id="desc" name="description"></div><button class="btn primary">সংরক্ষণ</button></form></section>
<section class="panel"><h2>ব্যয়ের তালিকা</h2><div class="table-wrap"><table><thead><tr><th>তারিখ</th><th>প্রকল্প</th><th>খাত</th><th>টাকা</th><th>বিবরণ</th><th>অবস্থা</th><th>অ্যাকশন</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['entry_date'])?></td><td><?=e($r['project_title'])?></td><td><?=e($r['head_name'])?></td><td>৳<?=number_format((float)$r['amount'],2)?></td><td><?=e($r['description'])?></td><td><?=e($r['status'])?></td><td><?php if(can('edit_expense',(int)$r['project_id'])):?><button class="btn" type="button" onclick='editExpense(<?=e(json_encode(["id"=>$r['id'],"project_id"=>$r['project_id'],"head_id"=>$r['head_id'],"advance_employee_id"=>$r['advance_employee_id'],"entry_date"=>$r['entry_date'],"amount"=>$r['amount'],"description"=>$r['description']],JSON_HEX_APOS|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_QUOT))?>)'>Edit</button><?php endif;?><?php if(is_admin()&&$r['status']==='pending'):?><form method="post" action="approve_expense.php" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn">Approve</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<script>function filterHeads(){let p=document.getElementById('pid').value,h=document.getElementById('hid');for(let o of h.options){if(o.value)o.hidden=o.dataset.project!==p;}if(h.selectedOptions[0]&&h.selectedOptions[0].hidden)h.value='';}function editExpense(r){document.getElementById('action').value='edit';document.getElementById('rid').value=r.id;document.getElementById('pid').value=r.project_id;filterHeads();document.getElementById('hid').value=r.head_id;document.getElementById('emp').value=r.advance_employee_id||0;document.getElementById('dt').value=r.entry_date;document.getElementById('amt').value=r.amount;document.getElementById('desc').value=r.description||'';window.scrollTo({top:0,behavior:'smooth'});}filterHeads();</script>
<?php include 'layout_bottom.php';?>
